// Q1: call load on the real call center path, generated by Asterisk itself (no SIP client needed).
// Each simulated caller is a Local channel into 9000 (Stasis "internal-test" → the ACD): it hears
// the IVR, presses a digit, waits in the department queue, then hangs up. The ACD writes every call
// to cc_calls, which gives the timings:
//   setup  = originate → call row created (ARI event → ACD → PostgreSQL)
//   queued = call row → queued_at (IVR prompt + digit + routing)
// Usage: npm run build --workspace @doan/api && node scripts/benchmarks/callcenter-load.mjs --calls 40 --concurrency 20
// Options: --hold <s> seconds in queue (8), --digit <d> IVR choice (1), --keep to keep the rows.
// Test calls use caller numbers 0999xxxxxx and are deleted afterwards (their missed-call tickets too).
// Put agents on "Tạm nghỉ" first unless you want their phones to ring.
import { performance } from "node:perf_hooks";
import process from "node:process";
import "../../dist/api/config/env.js";
import { pool } from "../../dist/api/infrastructure/database/db.js";

const arg = (name, fallback) => {
  const index = process.argv.indexOf(`--${name}`);
  return index > 0 ? process.argv[index + 1] : fallback;
};
const calls = Number(arg("calls", 20));
const concurrency = Number(arg("concurrency", 10));
const holdMs = Number(arg("hold", 8)) * 1000;
const digit = arg("digit", "1");
const keep = process.argv.includes("--keep");
if (!process.env.ASTERISK_ARI_PASSWORD) throw new Error("ASTERISK_ARI_PASSWORD is required");

const base = `${(process.env.ASTERISK_ARI_URL ?? "http://localhost:8088").replace(/\/$/, "")}/ari`;
const auth = `Basic ${Buffer.from(`${process.env.ASTERISK_ARI_USER ?? "nexo"}:${process.env.ASTERISK_ARI_PASSWORD}`).toString("base64")}`;
const ari = async (method, path) => {
  const response = await fetch(base + path, { method, headers: { Authorization: auth }, signal: AbortSignal.timeout(5000) });
  if (!response.ok) throw new Error(`${method} ${path.split("?")[0]} → ${response.status}`);
  return response.status === 204 ? null : response.json();
};
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
const percentile = (values, p) => {
  if (!values.length) return null;
  const sorted = [...values].sort((a, b) => a - b);
  return Math.round(sorted[Math.min(sorted.length - 1, Math.floor((p / 100) * sorted.length))]);
};

const startedAt = new Date();
const run = String(Date.now() % 1000).padStart(3, "0");
const originated = new Map(); // caller number → epoch ms of the originate request
const errors = [];
let next = 0;

async function caller(index) {
  const callerNumber = `0999${run}${String(index).padStart(3, "0")}`; // 10 digits, unique in this run
  originated.set(callerNumber, Date.now());
  const params = new URLSearchParams({ endpoint: "Local/9000@from-internal", app: "nexo", appArgs: "loadtest", callerId: callerNumber });
  const channel = await ari("POST", `/channels?${params}`);
  try {
    await sleep(1500); // let the IVR prompt start
    await ari("POST", `/channels/${channel.id}/dtmf?dtmf=${digit}`);
    await sleep(holdMs);
  } finally {
    await ari("DELETE", `/channels/${channel.id}`).catch(() => {});
  }
}

const t0 = performance.now();
await Promise.all(
  Array.from({ length: Math.min(concurrency, calls) }, async () => {
    while (next < calls) {
      const index = next++;
      await caller(index).catch((error) => errors.push(error.message));
    }
  }),
);
const wallSeconds = (performance.now() - t0) / 1000;
await sleep(2000); // the ACD finishes writing ended calls

const rows = (
  await pool.query(
    `SELECT id,caller_number,started_at,queued_at,outcome FROM cc_calls WHERE caller_number LIKE '0999%' AND started_at >= $1`,
    [startedAt],
  )
).rows;
const setup = rows.filter((row) => originated.has(row.caller_number)).map((row) => row.started_at.getTime() - originated.get(row.caller_number));
const queued = rows.filter((row) => row.queued_at).map((row) => row.queued_at - row.started_at);
const outcomes = rows.reduce((all, row) => ({ ...all, [row.outcome ?? "open"]: (all[row.outcome ?? "open"] ?? 0) + 1 }), {});

console.log(JSON.stringify({
  calls, concurrency, holdSeconds: holdMs / 1000, wallSeconds: Number(wallSeconds.toFixed(1)),
  recorded: rows.length, failedToOriginate: errors.length, errors: [...new Set(errors)].slice(0, 5),
  setupMs: { p50: percentile(setup, 50), p95: percentile(setup, 95), max: percentile(setup, 100) },
  ivrToQueueMs: { p50: percentile(queued, 50), p95: percentile(queued, 95), max: percentile(queued, 100) },
  outcomes,
}, null, 2));

if (!keep && rows.length) {
  const ids = rows.map((row) => row.id);
  await pool.query(`DELETE FROM cc_tickets WHERE call_id=ANY($1::uuid[])`, [ids]);
  await pool.query(`DELETE FROM cc_calls WHERE id=ANY($1::uuid[])`, [ids]);
}
await pool.end();
